struct Resource {};
// Preferred creation method
std::unique_ptr<Resource> p1 = std::make_unique<Resource>();

// Access via -> or *
p1->method();

// Transfer ownership via move
std::unique_ptr<Resource> p2 = std::move(p1);

// p1 is now nullptr
if (!p1) {}

// Custom deleter (lambda)
auto custom_del = [](Resource* r) { delete r; };
std::unique_ptr<Resource, decltype(custom_del)> p3(new Resource(), custom_del);

