struct Task {};
// Creation
std::shared_ptr<Task> s1 = std::make_shared<Task>();

// Copying is allowed (reference count +1)
std::shared_ptr<Task> s2 = s1;

// Current reference count
long count = s1.use_count(); // count == 2

// Resource deleted when count reaches zero
s1.reset(); // count == 1

// ----------------------------------------

auto s_owner = std::make_shared<int>(42);

// Create non-owning reference
std::weak_ptr<int> w_ref = s_owner;

// Check validity and acquire temporary ownership
if (auto s_locked = w_ref.lock()) {
    // Use s_locked
    int val = *s_locked;
}

s_owner.reset(); // Resource deleted

if (w_ref.expired()) {
    // Cannot lock, resource gone
}
